// ParseTransformSpecTimestampField extracts the top-level timestamp_field configured on Master transform_spec.
func ParseTransformSpecTimestampField(specRaw string) string {
	if strings.TrimSpace(specRaw) == "" {
		return ""
	}
	var spec struct {
		TimestampField string `json:"timestamp_field"`
	}
	if err := json.Unmarshal([]byte(specRaw), &spec); err != nil {
		return ""
	}
	return strings.TrimSpace(spec.TimestampField)
}

func snakeToCamelIdent(s string) string {
	s = strings.TrimSpace(s)
	if s == "" || !strings.Contains(s, "_") || strings.HasPrefix(s, "_") {
		return s
	}
	parts := strings.Split(s, "_")
	var b strings.Builder
	for i, p := range parts {
		if p == "" {
			continue
		}
		if i == 0 {
			b.WriteString(strings.ToLower(p))
			continue
		}
		b.WriteString(strings.ToUpper(p[:1]))
		if len(p) > 1 {
			b.WriteString(strings.ToLower(p[1:]))
		}
	}
	return b.String()
}

func mongoTimestampCandidates(timestampField string) []string {
	tsCol := strings.TrimSpace(timestampField)
	if tsCol == "" || tsCol == "_source_ts" {
		return []string{"_source_ts"}
	}
	seen := make(map[string]struct{}, 3)
	var out []string
	add := func(v string) {
		v = strings.TrimSpace(v)
		if v == "" {
			return
		}
		if _, exists := seen[v]; !exists {
			seen[v] = struct{}{}
			out = append(out, v)
		}
	}
	add(tsCol)
	add(snakeToCamelIdent(tsCol))
	add(camelToSnake(tsCol))
	return out
}

func (rc *ReconCore) resolveSegmentBTSCol(ctx context.Context, ref MasterBindingRef, checkType string) string {
	tsCol := "_source_ts"
	specTS := ParseTransformSpecTimestampField(ref.TransformSpec)
	if rc.registryRepo != nil {
		if entry, err := rc.registryRepo.GetByTargetTableAndSchema(ctx, ref.ShadowTable, ref.ShadowSchema); err == nil && entry != nil {
			if specTS != "" && (entry.TimestampField == nil || strings.TrimSpace(*entry.TimestampField) == "") {
				entry.TimestampField = &specTS
			}
			_, dstTS, errTS := rc.resolveSourceAndDestTSFields(ctx, *entry, checkType)
			if errTS == nil && dstTS != "" {
				tsCol = dstTS
			}
		}
	}
	if tsCol == "_source_ts" && specTS != "" && rc.destAgent != nil {
		shadowRel := ref.ShadowRel()
		for _, cand := range []string{specTS, camelToSnake(specTS)} {
			if realCol, err := rc.destAgent.GetRealColumnName(ctx, shadowRel, cand); err == nil && realCol != "" {
				tsCol = realCol
				break
			}
		}
	}
	return tsCol

