func buildMongoWindowFilter(timestampField string, tLo, tHi time.Time, deletedFilter bson.M) bson.M {
	tsCol := strings.TrimSpace(timestampField)
	if tsCol == "" {
		tsCol = "_source_ts"
	}
	loMs := tLo.UnixMilli()
	hiMs := tHi.UnixMilli()
	var filter bson.M
	if tsCol == "_source_ts" {
		filter = bson.M{
			"_source_ts": bson.M{
				"$gte": loMs,
				"$lt":  hiMs,
			},
		}
	} else {
		// [FIX OB-05]: Support both BSON DateTime and int64 epoch-ms representations across snake_case / camelCase timestamp fields
		var orClauses bson.A
		for _, cand := range mongoTimestampCandidates(tsCol) {
			orClauses = append(orClauses,
				bson.M{
					cand: bson.M{
						"$gte": primitive.NewDateTimeFromTime(tLo.UTC()),
						"$lt":  primitive.NewDateTimeFromTime(tHi.UTC()),
					},
				},
				bson.M{
					cand: bson.M{
						"$gte": loMs,
						"$lt":  hiMs,
					},
				},
			)
		}
		filter = bson.M{"$or": orClauses}
	}
	for k, v := range deletedFilter {
		filter[k] = v
	}
	return filter
}

