func parseMongoTimestampMs(rawTs any) (int64, bool) {
	if rawTs == nil {
		return 0, false
	}
	switch x := rawTs.(type) {
	case int64:
		return x, true
	case int32:
		return int64(x), true
	case int:
		return int64(x), true
	case float64:
		return int64(x), true
	case primitive.DateTime:
		return x.Time().UnixMilli(), true
	case time.Time:
		return x.UnixMilli(), true
	default:
		return 0, false
	}
}

func extractMongoDocIDAndTsMs(doc bson.M, pkColumn, tsCol string) (string, int64, bool) {
	rawID, ok := doc[pkColumn]
	if !ok || rawID == nil {
		rawID = doc["_gpay_id"]
	}
	if rawID == nil {
		return "", 0, false
	}
	var idStr string
	switch v := rawID.(type) {
	case primitive.ObjectID:
		idStr = v.Hex()
	default:
		idStr = fmt.Sprintf("%v", v)
	}
	if idStr == "" {
		return "", 0, false
	}

	var tsMs int64
	for _, cand := range mongoTimestampCandidates(tsCol) {
		if parsed, ok := parseMongoTimestampMs(doc[cand]); ok {
			tsMs = parsed
			break
		}
	}
	return idStr, tsMs, true
}

